#!/usr/bin/env python3
"""Regenerate nfkc_tables.go from this interpreter's unicodedata.

usage: python3 -I testdata/gen_nfkc.py > nfkc_tables.go   (run from internal/adapter)

Only the code points whose NFKC form contains printable ASCII are tabled (the full-width forms, the
compatibility letters and digits, the dot leaders, ...): those are the ones that can smuggle a
separator, a dot or a URI scheme past the path checks in manifest.go. Runs of consecutive code points
that map to consecutive single ASCII characters are one entry.
"""
import unicodedata as ud

entries = []  # (lo, hi, dst) for 1->1 runs, or (cp, None, string)
cps = []
for cp in range(0x110000):
    if 0xD800 <= cp <= 0xDFFF:
        continue
    n = ud.normalize("NFKC", chr(cp))
    if n != chr(cp) and any(0x20 <= ord(x) < 0x7F for x in n):
        cps.append((cp, n))

i = 0
while i < len(cps):
    cp, n = cps[i]
    if len(n) == 1:
        j = i
        while j + 1 < len(cps) and cps[j + 1][0] == cps[j][0] + 1 and len(cps[j + 1][1]) == 1 and ord(cps[j + 1][1]) == ord(cps[j][1]) + 1:
            j += 1
        if j > i:
            entries.append((cp, cps[j][0], n))
            i = j + 1
            continue
    entries.append((cp, None, n))
    i += 1

print("// Code generated by testdata/gen_nfkc.py; DO NOT EDIT.")
print()
print("package adapter")
print()
print('const nfkcUnicodeVersion = "%s"' % ud.unidata_version)
print()
print("// nfkcRuns are 1:1 runs: code points lo..hi map to dst, dst+1, ...")
print("var nfkcRuns = [...]struct{ lo, hi, dst rune }{")
for lo, hi, n in entries:
    if hi is not None:
        print("\t{0x%X, 0x%X, %r}," % (lo, hi, n))
print("}")
print()
print("// nfkcSingles map one code point to its NFKC text.")
print("var nfkcSingles = map[rune]string{")
for lo, hi, n in entries:
    if hi is None:
        print("\t0x%X: %s," % (lo, '"' + "".join(c if c not in '"\\' else "\\" + c for c in n) + '"'))
print("}")
